/*GIONG-VIET-BAT*/
const GIONG_VIET = {"Chào mừng các bạn đến với Bé ngoan mỗi ngày, môn Đạo đức!": "data:audio/mpeg;base64,", "Các bạn được ba sao! Giỏi quá!": "data:audio/mpeg;base64,", "Các bạn được hai sao! Cố lên nữa nhé!": "data:audio/mpeg;base64,", "Các bạn được một sao! Mình cùng ôn lại nhé!": "data:audio/mpeg;base64,", "Mình cùng ôn lại bài nhé!": "data:audio/mpeg;base64,", "Chưa đúng rồi, các bạn thử lại nhé!": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Nhà Yêu Thương!": "data:audio/mpeg;base64,", "Bạn nào đã biết giữ vệ sinh đôi tay? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bạn rửa tay sạch sẽ là biết giữ vệ sinh đôi tay. Chùi tay vào áo, cho tay lên mũi là chưa sạch.": "data:audio/mpeg;base64,", "Chưa rửa tay đã cầm thức ăn là việc nên làm. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Em luôn giữ đôi tay sạch sẽ hằng ngày, rửa tay trước khi ăn.": "data:audio/mpeg;base64,", "Bạn nào chưa biết giữ vệ sinh răng miệng? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bạn nói «Con không đánh răng đâu ạ!» là chưa biết giữ vệ sinh răng miệng. Chải răng mỗi ngày, hai lần sáng, tối.": "data:audio/mpeg;base64,", "Mỗi ngày em nên chải răng mấy lần? A. Hai lần: buổi sáng và buổi tối. B. Không cần chải răng. C. Một tuần một lần.": "data:audio/mpeg;base64,", "Bạn ơi hãy nhớ: chải răng mỗi ngày, hai lần sáng, tối.": "data:audio/mpeg;base64,", "Bạn nào chưa biết giữ cơ thể sạch sẽ? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bạn có quần áo, mặt mũi lấm bẩn là chưa giữ cơ thể sạch sẽ. Em luôn tắm, gội sạch sẽ hằng ngày.": "data:audio/mpeg;base64,", "Xếp các tranh theo đúng thứ tự khi tắm.": "data:audio/mpeg;base64,", "Đầu tóc gọn gàng, hằng ngày tắm gội, mình càng đẹp xinh.": "data:audio/mpeg;base64,", "Bạn nào chưa biết giữ trang phục gọn gàng? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Quần áo vứt bừa bãi trên sàn là chưa gọn gàng. Giữ gìn trang phục gọn gàng, thơm tho, sạch sẽ.": "data:audio/mpeg;base64,", "Cởi áo vứt xuống sân trường để đá bóng là việc nên làm. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Em rèn thói quen giữ trang phục gọn gàng, sạch sẽ.": "data:audio/mpeg;base64,", "Gia đình bạn nhỏ gồm những ai? A. Ông bà, bố mẹ, bạn nhỏ và em gái. B. Chỉ có bạn nhỏ. C. Cô giáo và các bạn.": "data:audio/mpeg;base64,", "Gia đình bạn nhỏ có ông bà, bố mẹ, bạn nhỏ và em gái.": "data:audio/mpeg;base64,", "Khi lạc nhà, thỏ con gặp điều gì? A. Bị sói đuổi, bị đói và bị mưa rét. B. Được ăn no, chơi vui. C. Gặp mẹ ngay.": "data:audio/mpeg;base64,", "Thỏ con lạc nhà gặp nhiều nguy hiểm. Ai cũng cần có gia đình yêu thương, chăm sóc.": "data:audio/mpeg;base64,", "Việc làm nào thể hiện tình yêu thương trong gia đình?": "data:audio/mpeg;base64,", "Em yêu gia đình nhỏ, có ông bà, mẹ cha, anh chị em ruột thịt, tình thương mến chan hoà.": "data:audio/mpeg;base64,", "Bạn nào chưa biết lễ phép, vâng lời? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bạn nói «Không! Phim đang hay mà ông» là chưa vâng lời. Bé ngoan lễ phép, vâng lời ông bà, cha mẹ.": "data:audio/mpeg;base64,", "Việc nào nên làm, việc nào không nên làm với ông bà?": "data:audio/mpeg;base64,", "Quan tâm, chăm sóc ông bà, biết ơn, hiếu thảo — em là cháu ngoan.": "data:audio/mpeg;base64,", "Bố em đi làm về vừa nóng, vừa mệt. Em sẽ làm gì? A. Lấy nước mời bố, hỏi han bố. B. Đòi bố cho đi chơi ngay. C. Không để ý đến bố.": "data:audio/mpeg;base64,", "Quan tâm, chăm sóc mẹ cha, em luôn ghi nhớ mới là con ngoan.": "data:audio/mpeg;base64,", "Việc nào KHÔNG nên làm với em nhỏ? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Tranh giành đồ chơi với em là không nên. Anh em chung một mái nhà, quan tâm, giúp đỡ, chan hoà yêu thương.": "data:audio/mpeg;base64,", "Nếu là anh, chị của em bé đang khóc, em sẽ làm gì? A. Dỗ dành, chơi cùng em. B. Mặc kệ em khóc. C. Mắng em.": "data:audio/mpeg;base64,", "Em hãy thể hiện sự chăm sóc, giúp đỡ em nhỏ bằng những việc làm phù hợp.": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Trường Nề Nếp!": "data:audio/mpeg;base64,", "Mải chơi điện tử nên vào lớp muộn là việc đáng đồng tình. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Nội quy mình nhớ khắc ghi, đến trường học tập em đi đúng giờ.": "data:audio/mpeg;base64,", "Việc nào không nên làm? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Đã đến giờ dậy mà còn đòi ngủ thêm thì dễ đi học muộn. Chuẩn bị sách vở từ tối hôm trước là việc nên làm.": "data:audio/mpeg;base64,", "Nhờ bạn viết hộ bài là không nên. Học bài, làm bài đầy đủ, em giỏi, bạn, thầy yêu.": "data:audio/mpeg;base64,", "Gặp bài khó, em sẽ làm gì? A. Cố gắng suy nghĩ, hỏi cô giáo hoặc bạn. B. Bỏ dở không làm nữa. C. Chép bài của bạn.": "data:audio/mpeg;base64,", "Em cùng các bạn nhắc nhau học bài, làm bài đầy đủ.": "data:audio/mpeg;base64,", "Lớp nào đang giữ trật tự? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Cả lớp ngồi ngay ngắn nghe cô giảng bài là giữ trật tự. Trật tự trong trường, lớp — em là học trò ngoan.": "data:audio/mpeg;base64,", "Trong giờ học, bạn rủ: «Tớ có chuyện này hay lắm!». Em sẽ làm gì? A. Nhắc bạn để ra chơi rồi kể, giờ học phải trật tự. B. Quay sang nói chuyện ngay. C. Cười to trong lớp.": "data:audio/mpeg;base64,", "Em cùng các bạn nhắc nhau luôn giữ trật tự trong trường, lớp.": "data:audio/mpeg;base64,", "Việc làm nào giữ gìn tài sản của trường, lớp?": "data:audio/mpeg;base64,", "Tài sản chung của trường, ta cùng nhau gìn giữ.": "data:audio/mpeg;base64,", "Hái hoa trong vườn trường là việc nên làm. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Em nhắc bạn không hái hoa. Cùng nhau giữ gìn tài sản của trường, lớp.": "data:audio/mpeg;base64,", "Em đồng tình hay không đồng tình với việc làm của bạn?": "data:audio/mpeg;base64,", "Cùng nhau gìn giữ vệ sinh, trường lớp sạch đẹp, chúng mình khoẻ, vui.": "data:audio/mpeg;base64,", "Đi vệ sinh xong, mất nước thì thôi kệ, không cần báo ai. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Em cần báo cô giáo hoặc người lớn để giữ nhà vệ sinh luôn sạch sẽ.": "data:audio/mpeg;base64,", "Để đồ dùng, quần áo bừa bãi khắp phòng là gọn gàng, ngăn nắp. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Đồ dùng, sách vở, đồ chơi, để cho ngăn nắp, đúng nơi, dễ tìm.": "data:audio/mpeg;base64,", "Em cần làm gì để sách vở, đồ dùng luôn gọn gàng? A. Xếp sách vở, đồ dùng đúng chỗ sau khi dùng. B. Vứt đồ dùng khắp nơi. C. Để mẹ dọn hết cho em.": "data:audio/mpeg;base64,", "Đồ dùng, sách vở, đồ chơi, để cho ngăn nắp, đúng nơi, dễ tìm.": "data:audio/mpeg;base64,", "Xếp các tranh theo thứ tự một ngày của bạn nhỏ (xem đồng hồ nhé).": "data:audio/mpeg;base64,", "Học tập, sinh hoạt đúng giờ giúp em mạnh khoẻ, lấy cờ thi đua.": "data:audio/mpeg;base64,", "Em không đồng tình với bạn nào? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Vừa ăn vừa đọc truyện là chưa đúng giờ nào việc nấy. Học tập, sinh hoạt đúng giờ có lợi cho sức khoẻ.": "data:audio/mpeg;base64,", "Chơi phi máy bay giấy trong giờ ngủ trưa là đúng. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Em khuyên bạn ngủ trưa đúng giờ, không làm ồn ảnh hưởng các bạn.": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Vườn Thật Thà!": "data:audio/mpeg;base64,", "Bạn nào đã tự giác học tập?": "data:audio/mpeg;base64,", "Em luôn tự giác học hành, chuyên cần, tích cực mới thành trò ngoan.": "data:audio/mpeg;base64,", "Ngồi đọc truyện, không ra tập thể dục cùng các bạn là tự giác. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Em khuyên bạn ra tập thể dục cùng cả lớp.": "data:audio/mpeg;base64,", "Ở trường, em cần tự giác tham gia những hoạt động nào? A. Trực nhật, trồng cây, giúp đỡ người khó khăn, chơi cùng bạn. B. Chỉ ngồi một chỗ. C. Không tham gia gì.": "data:audio/mpeg;base64,", "Tham gia hoạt động ở trường: tích cực, tự giác, hoà đồng bạn ơi!": "data:audio/mpeg;base64,", "Bạn nào tự giác ủng hộ bạn có hoàn cảnh khó khăn? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Bạn để dành tiền ủng hộ bạn có hoàn cảnh khó khăn là tự giác tham gia hoạt động ở trường.": "data:audio/mpeg;base64,", "Bạn nào tự giác, bạn nào chưa tự giác làm việc nhà?": "data:audio/mpeg;base64,", "Tuổi nhỏ làm việc nhỏ, tự giác giúp mẹ cha, chăm chỉ không quản ngại, cả nhà vui chan hoà.": "data:audio/mpeg;base64,", "Đại bàng nâu đã nói dối mẹ điều gì? A. Nói đã luyện tập tốt nhưng thật ra chỉ ngủ. B. Nói mình bị ốm. C. Nói đã đi học.": "data:audio/mpeg;base64,", "Đại bàng nâu nói dối nên không biết bay, bị rơi xuống nước. Chúng ta không nên nói dối.": "data:audio/mpeg;base64,", "Bạn nào đã nói dối mẹ? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bạn đang chơi xếp hình mà nói «Con đang ôn bài ạ!» là nói dối. Miệng xinh lời nói thật thà.": "data:audio/mpeg;base64,", "Cô kiểm tra đồ dùng học tập mà em quên bút chì. Em sẽ nói gì với cô? A. Thưa cô, em quên bút chì ạ. B. Em có mang ạ. C. Không nói gì.": "data:audio/mpeg;base64,", "Em luôn nói lời chân thật. Thầy yêu, bạn mến, mẹ cha vui lòng.": "data:audio/mpeg;base64,", "Tự ý lấy đồ chơi của bạn mang về nhà là đúng. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Đồ dùng của riêng ai, mỗi khi cần sử dụng, nhớ hỏi xin, hỏi mượn, không tự ý lấy dùng.": "data:audio/mpeg;base64,", "Bạn nào đáng khen? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Bạn hỏi mượn bút trước khi dùng là đáng khen. Bạn lấy thước khi chưa hỏi cần được nhắc nhở.": "data:audio/mpeg;base64,", "Việc nào nên làm, việc nào không nên làm?": "data:audio/mpeg;base64,", "Đồ dùng của riêng ai, mỗi khi cần sử dụng, nhớ hỏi xin, hỏi mượn, không tự ý lấy dùng.": "data:audio/mpeg;base64,", "Tôm và Tép nhặt được của rơi đã làm gì? A. Trả lại cho bà cụ đánh mất. B. Giữ lại làm của mình. C. Vứt đi.": "data:audio/mpeg;base64,", "Tôm và Tép trả lại của rơi nên được bà khen ngoan. Của rơi là của người ta, nếu em nhặt được, thật thà trả ngay.": "data:audio/mpeg;base64,", "«Mình nhặt được là của mình.» Bạn nói như vậy là đúng. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Nhặt được của rơi, em trả lại người đánh mất hoặc nhờ người lớn tìm cách trả lại.": "data:audio/mpeg;base64,", "Bạn nào chưa biết nhận lỗi? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Đá bóng làm vỡ kính rồi rủ nhau trốn đi là chưa biết nhận lỗi. Mỗi khi em mắc lỗi, hãy nói lời xin lỗi.": "data:audio/mpeg;base64,", "Em lỡ làm vỡ lọ hoa, mẹ hỏi «Ai làm vỡ lọ hoa đây?». Em sẽ làm gì? A. Nhận lỗi và xin lỗi mẹ. B. Đổ lỗi cho chú chó. C. Trốn đi.": "data:audio/mpeg;base64,", "Biết nhận ra sai lầm, hãy nói lời xin lỗi, em thấy lòng mình vui.": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Pháo Đài An Toàn!": "data:audio/mpeg;base64,", "Hành vi nào an toàn, hành vi nào không an toàn khi tham gia giao thông?": "data:audio/mpeg;base64,", "Đi bộ quan sát trước sau, ngồi trên xe máy, mũ mau đội vào.": "data:audio/mpeg;base64,", "Em đi bộ trên vỉa hè (hoặc lề đường bên phải) và quan sát cẩn thận khi qua đường. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Em rèn thói quen đi bộ trên vỉa hè, đội mũ bảo hiểm khi đi xe máy, quan sát cẩn thận khi qua đường.": "data:audio/mpeg;base64,", "Việc nào nên làm để phòng, tránh đuối nước? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Đi bơi có phao, có người lớn bên cạnh là an toàn. Chơi xa sông, xa hồ; học bơi và quan sát.": "data:audio/mpeg;base64,", "Để phòng, tránh đuối nước: chơi xa sông, xa hồ, học bơi và quan sát, đi thuyền mặc áo phao.": "data:audio/mpeg;base64,", "Trong tranh, những gì có thể gây bỏng? A. Bô xe máy, chảo dầu nóng, bàn là, ấm nước sôi. B. Quả táo, cái ghế. C. Tấm thảm, chậu cây.": "data:audio/mpeg;base64,", "Pô xe, phích nước, bàn là, bếp đun, lửa nóng… tránh xa, chớ gần.": "data:audio/mpeg;base64,", "Việc nào nên làm, việc nào không nên làm để phòng, tránh bỏng?": "data:audio/mpeg;base64,", "Em thực hiện một số cách đơn giản và phù hợp để phòng, tránh bị bỏng.": "data:audio/mpeg;base64,", "Đốt lửa để chơi là trò chơi an toàn. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Lửa nóng có thể gây bỏng. Em khuyên bạn không nghịch lửa.": "data:audio/mpeg;base64,", "Bạn nào đang phòng, tránh bị ngã đúng cách? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Đội mũ, đeo đồ bảo vệ khi trượt patin là an toàn. Chạy trên thang cuốn, trèo lên lưng trâu dễ bị ngã.": "data:audio/mpeg;base64,", "Trèo lên cây cao để chơi là an toàn. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Trèo leo thương tích rất cao. Đừng nên chạy nhảy ở nơi trơn.": "data:audio/mpeg;base64,", "Bạn nào đã biết phòng, tránh điện giật? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Tránh xa dây điện bị đứt là đúng. Chọc tay vào ổ điện, chơi gần trạm điện rất nguy hiểm.": "data:audio/mpeg;base64,", "Áo bị ném lên cột điện, em trèo lên lấy là đúng. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Không chơi gần đường điện. Em nhờ người lớn giúp đỡ.": "data:audio/mpeg;base64,", "Việc nào nên làm, việc nào không nên làm để phòng, tránh ngộ độc thực phẩm?": "data:audio/mpeg;base64,", "Nhớ điều ăn chín uống sôi. Thực phẩm quá hạn, đồ ôi không dùng.": "data:audio/mpeg;base64,", "Em của Hiếu muốn mua nước ngọt có màu xanh, đỏ ở hội chợ. Nếu là Hiếu, em sẽ nói gì? A. Không nên mua, uống nước không rõ nguồn gốc dễ bị ngộ độc. B. Mua thật nhiều. C. Uống luôn không cần hỏi.": "data:audio/mpeg;base64,", "Thực phẩm quá hạn, đồ ôi không dùng. Em phòng, tránh ngộ độc thực phẩm.": "data:audio/mpeg;base64,", "Quy tắc 5 ngón tay: nối mỗi ngón tay với cách cư xử.": "data:audio/mpeg;base64,", "Ôm hôn người thân ruột thịt; nắm tay bạn bè, thầy cô; bắt tay người quen; vẫy tay người lạ; xua tay, hét to, bỏ chạy khi người lạ có cử chỉ thân mật.": "data:audio/mpeg;base64,", "Không được cho người khác chạm vào miệng, ngực, giữa hai đùi và mông của mình. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Hãy bảo vệ cơ thể, để phòng kẻ xấu xa.": "data:audio/mpeg;base64,", "Em chọn việc nên làm để phòng, tránh bị xâm hại. Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Chống lại và hét to khi người lạ muốn ôm, hôn. Không đi một mình ở nơi tối, vắng vẻ.": "data:audio/mpeg;base64,", "Người lạ nói: «Cháu bé, vào nhà chú chơi, chú có nhiều đồ ăn ngon lắm!». Em sẽ làm gì? A. Từ chối, chạy về và kể với bố mẹ. B. Đi theo chú ngay. C. Nhận đồ ăn của chú.": "data:audio/mpeg;base64,", "Từ chối nhận quà của người lạ. Bị kẻ nào xâm hại, tìm người để sẻ chia.": "data:audio/mpeg;base64,"};
let __amDang = null, __giongMay = null;
function __chuanGiong(t){ return String(t).normalize("NFC").replace(/\s+/g, " ").trim(); }
function __choDeNghe(t){
  const doi = [["π"," pi "],["cm³"," xăng-ti-mét khối"],["cm²"," xăng-ti-mét vuông"],["dm³"," đề-xi-mét khối"],["m³"," mét khối"],
    ["m²"," mét vuông"],["×"," nhân "],["÷"," chia "],["−"," trừ "],["≈"," xấp xỉ "],["="," bằng "],["+"," cộng "]];
  t = String(t).replace(/<[^>]+>/g, "");
  for (const [a, b] of doi) t = t.split(a).join(b);
  return __chuanGiong(t.replace(/(\d)\s*cm\b/g, "$1 xăng-ti-mét").replace(/(\d)\s*m\b/g, "$1 mét"));
}
function __timGiongMay(){ try { const ds = speechSynthesis.getVoices().filter(v => /^vi/i.test(v.lang));
  __giongMay = ds.find(v => /Natural|Online|HoaiMy|Hoài/i.test(v.name)) || ds[0] || null; } catch(e){} return __giongMay; }
try { if (window.speechSynthesis){ __timGiongMay(); speechSynthesis.addEventListener("voiceschanged", __timGiongMay); } } catch(e){}
function coGiongViet(chu){ return !!(GIONG_VIET[__chuanGiong(chu)] || __giongMay || __timGiongMay()); }
function dungGiong(){ try { if (__amDang){ __amDang.pause(); __amDang = null; } if (window.speechSynthesis) speechSynthesis.cancel(); } catch(e){} }
function __baoChuaCoGiong(){ try { if (document.getElementById("__baoGiong")) return; const d = document.createElement("div"); d.id = "__baoGiong";
  d.setAttribute("role", "status");
  d.textContent = "Máy chưa có giọng đọc tiếng Việt cho câu này. Mở bằng Microsoft Edge (có mạng) để nghe giọng Việt, hoặc cài thêm giọng Tiếng Việt: Cài đặt Windows → Thời gian và ngôn ngữ → Giọng nói.";
  d.style.cssText = "position:fixed;left:50%;bottom:18px;transform:translateX(-50%);max-width:92vw;background:#1f2937;color:#fff;padding:12px 16px;border-radius:12px;font:15px/1.4 system-ui,sans-serif;z-index:99999;box-shadow:0 6px 20px rgba(0,0,0,.3)";
  document.body.appendChild(d); setTimeout(() => d.remove(), 7000); } catch(e){} }
function __docMay(chu, toc){
  if (!__giongMay){ __baoChuaCoGiong(); return; }   // KHÔNG có giọng Việt → báo, không đọc bằng giọng Anh
  const u = new SpeechSynthesisUtterance(chu); u.voice = __giongMay; u.lang = __giongMay.lang; u.rate = toc || 0.9; speechSynthesis.speak(u);
}
function docGiongViet(goc, chuMay, toc){
  dungGiong(); const k = __chuanGiong(goc);
  if (GIONG_VIET[k]){ try { __amDang = new Audio(GIONG_VIET[k]); const h = __amDang.play(); if (h && h.catch) h.catch(() => {}); return; } catch(e){} }
  try { if (!window.speechSynthesis){ __baoChuaCoGiong(); return; }
    const chu = chuMay || __choDeNghe(goc);
    if (!__giongMay && !__timGiongMay() && !speechSynthesis.getVoices().length){   // Chrome nạp danh sách giọng chậm
      setTimeout(() => { __timGiongMay(); __docMay(chu, toc); }, 700); return; }
    __docMay(chu, toc); } catch(e){}
}
/*GIONG-VIET-HET*/